package com.xiaobu.ledger.infrastructure;

import java.time.LocalDate;
import java.util.List;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.Repository;
import org.springframework.data.repository.query.Param;

interface LedgerStatementJpaRepository extends Repository<LedgerTransactionEntity, String> {
  // MySQL 5.7 rejects the derived-table column alias list generated by Hibernate HQL.
  // Share the same parameterized union between rows and totals, without loading either source in
  // Java.
  String STATEMENT =
      """
      FROM (
        SELECT t.id, t.direction, t.amount_cents, t.booked_on, t.category_code, t.note,
               t.account_id, NULL AS original_id, t.created_at, 0 AS kind
        FROM ledger_transactions t
        WHERE t.ledger_id = :ledger AND t.deleted = 0
          AND t.booked_on BETWEEN :from AND :through
          AND (:keyword = '' OR LOCATE(LOWER(:keyword), LOWER(t.note)) > 0)
        UNION ALL
        SELECT r.id, original.direction, r.amount_cents, r.received_on, original.category_code,
               original.note, r.account_id, original.id, r.created_at, 1
        FROM ledger_refunds r
        INNER JOIN ledger_transactions original
            ON original.id = r.transaction_id AND original.ledger_id = r.ledger_id
        WHERE r.ledger_id = :ledger AND original.deleted = 0
          AND r.received_on BETWEEN :from AND :through
          AND (:keyword = '' OR LOCATE(LOWER(:keyword), LOWER(original.note)) > 0
              OR LOCATE(LOWER(:keyword), '退款') > 0)
      ) AS activity
      """;

  @Query(
      value =
          """
          SELECT id, direction, amount_cents AS amountCents, booked_on AS bookedOn,
                 category_code AS categoryCode, note, account_id AS accountId,
                 original_id AS originalTransactionId
          """
              + STATEMENT
              + """
              ORDER BY booked_on DESC, kind ASC, created_at DESC, id DESC
              LIMIT :limit OFFSET :offset
              """,
      nativeQuery = true)
  List<StatementRow> findPage(
      @Param("ledger") String ledgerId,
      @Param("from") LocalDate from,
      @Param("through") LocalDate through,
      @Param("keyword") String keyword,
      @Param("limit") int limit,
      @Param("offset") int offset);

  @Query(
      value =
          """
          SELECT booked_on AS bookedOn,
              SUM(CASE WHEN direction = 'INCOME' THEN amount_cents ELSE 0 END) AS incomeCents,
              SUM(CASE WHEN kind = 1 THEN -amount_cents
                       WHEN direction = 'EXPENSE' THEN amount_cents ELSE 0 END) AS expenseCents,
              COUNT(id) AS entryCount
          """
              + STATEMENT
              + " GROUP BY booked_on ORDER BY booked_on DESC",
      nativeQuery = true)
  List<StatementDay> summarizeByDay(
      @Param("ledger") String ledgerId,
      @Param("from") LocalDate from,
      @Param("through") LocalDate through,
      @Param("keyword") String keyword);

  interface StatementRow {
    String getId();

    String getDirection();

    Number getAmountCents();

    LocalDate getBookedOn();

    String getCategoryCode();

    String getNote();

    String getAccountId();

    String getOriginalTransactionId();
  }

  interface StatementDay {
    LocalDate getBookedOn();

    Number getIncomeCents();

    Number getExpenseCents();

    Number getEntryCount();
  }
}
